/* From Uiverse.io by ElSombrero2 (classes renomeadas com prefixo card-flip-perfil para evitar colisao com nomes genericos tipo .card/.front/.title) */
.card-flip-perfil {
  position: relative;
  overflow: visible;
  width: 190px;
  height: 254px;
}

.card-flip-perfil__content {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform 300ms;
  box-shadow: 0px 0px 10px 1px #000000ee;
  border-radius: 5px;
}

.card-flip-perfil__front,
.card-flip-perfil__back {
  background-color: #151515;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  border-radius: 5px;
  overflow: hidden;
}

.card-flip-perfil__back {
  justify-content: center;
  display: flex;
  align-items: center;
}

.card-flip-perfil__back::before {
  position: absolute;
  content: " ";
  display: block;
  width: 160px;
  height: 160%;
  background: linear-gradient(90deg, transparent, #ff9966, #ff9966, #ff9966, #ff9966, transparent);
  animation: card-flip-perfil-rotation 5000ms infinite linear;
}

.card-flip-perfil__back-content {
  position: absolute;
  width: 99%;
  height: 99%;
  background-color: #151515;
  border-radius: 5px;
  color: white;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 30px;
}

.card-flip-perfil:hover .card-flip-perfil__content {
  transform: rotateY(180deg);
}

@keyframes card-flip-perfil-rotation {
  0% {
    transform: rotateZ(0deg);
  }

  100% {
    transform: rotateZ(360deg);
  }
}

.card-flip-perfil__front {
  transform: rotateY(180deg);
  color: white;
}

.card-flip-perfil__front-content {
  position: absolute;
  width: 100%;
  height: 100%;
  padding: 10px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.card-flip-perfil__badge {
  background-color: #00000055;
  padding: 2px 10px;
  border-radius: 10px;
  backdrop-filter: blur(2px);
  width: fit-content;
  font-size: 11px;
}

.card-flip-perfil__description {
  box-shadow: 0px 0px 10px 5px #00000088;
  width: 100%;
  padding: 10px;
  background-color: #00000099;
  backdrop-filter: blur(5px);
  border-radius: 5px;
  font-size: 12px;
}

.card-flip-perfil__title {
  font-size: 11px;
  max-width: 100%;
  display: flex;
  justify-content: space-between;
}

.card-flip-perfil__title p {
  width: 50%;
  margin: 0;
}

.card-flip-perfil__footer {
  color: #ffffff88;
  margin-top: 5px;
  font-size: 8px;
}

.card-flip-perfil__img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.card-flip-perfil__circle {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background-color: #ffbb66;
  position: relative;
  filter: blur(15px);
  animation: card-flip-perfil-floating 2600ms infinite linear;
}

.card-flip-perfil__circle--bottom {
  background-color: #ff8866;
  left: 50px;
  top: 0px;
  width: 150px;
  height: 150px;
  animation-delay: -800ms;
}

.card-flip-perfil__circle--right {
  background-color: #ff2233;
  left: 160px;
  top: -80px;
  width: 30px;
  height: 30px;
  animation-delay: -1800ms;
}

@keyframes card-flip-perfil-floating {
  0% {
    transform: translateY(0px);
  }

  50% {
    transform: translateY(10px);
  }

  100% {
    transform: translateY(0px);
  }
}
